import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import { sourceInput } from '../src/lib/source-inputs';
import { analyzeBundle, introductionPaths } from '../src/server/source/analysis';
import { resultSchema } from '../src/server/source/jobs';
import { stageSourceInput } from '../src/server/source/lock-inputs';

// Generated by Bun 1.2.23. Workspace links are not registry packages.
const files = Object.fromEntries(['package.json', 'packages/analytics/package.json', 'bun.lock'].map(path =>
  [path, readFileSync(new URL(`./fixtures/bun-workspace/${path}`, import.meta.url), 'utf8')]));
const bundle = { files, commit: 'a'.repeat(40), hash: 'b'.repeat(64), collectedAt: 1 };
const report = { SchemaVersion: 2, Results: [{ Target: 'bun.lock', Type: 'bun', Packages: [{ Name: 'lodash', Version: '4.17.20', Dev: true }],
  Vulnerabilities: [{ PkgName: 'lodash', InstalledVersion: '4.17.20', VulnerabilityID: 'CVE-2021-23337' }] }] };

for (const version of [0, 1]) test(`Bun text v${version}: attribute a finding to a workspace dev dependency`, () => {
  const lock = files['bun.lock'].replace('"lockfileVersion": 1', `"lockfileVersion": ${version}`);
  assert.ok(sourceInput('bun.lock') && stageSourceInput('bun.lock', lock));
  const result = analyzeBundle({ ...bundle, files: { ...files, 'bun.lock': lock } }, report);
  resultSchema.shape.analysis.parse(result);
  assert.equal(result.manager, 'bun'); assert.deepEqual(result.warnings, []);
  assert.equal(result.coverage.inventory, 'complete'); assert.equal(result.nodes.length, 1);
  assert.equal(result.findings[0].node, 'bun.lock#lodash');
  assert.equal(result.edges.find(e => e.to === result.findings[0].node)?.scope, 'development');
  assert.ok(introductionPaths(result, result.findings[0].node).paths.some(path => path.length === 3));
});

test('malformed, future and binary Bun locks are neither staged nor assessed as clean', () => {
  for (const [file, raw] of [['bun.lock', '{'], ['bun.lock', files['bun.lock'].replace('"lockfileVersion": 1', '"lockfileVersion": 99')], ['bun.lockb', 'binary']]) {
    assert.ok(sourceInput(file)); assert.equal(stageSourceInput(file, raw), false);
    const result = analyzeBundle({ ...bundle, files: { [file]: raw } }, { SchemaVersion: 2, Results: [] });
    assert.equal(result.coverage.inventory, 'unknown'); assert.ok(result.warnings.some(w => w.includes(file)));
  }
});

test('another target cannot establish Bun inventory coverage or supply its findings', () => {
  const result = analyzeBundle(bundle, { SchemaVersion: 2, Results: [{ ...report.Results[0], Target: 'nested/bun.lock' }] });
  assert.equal(result.coverage.inventory, 'unknown'); assert.deepEqual(result.findings, []);
});
